        Ok(metadata) => metadata,
        Err(error) => return result(io_result(error)),
    };
    if !initial.file_type().is_file() {
        return result(Error::NotRegular);
    }

    let original = match open_regular_nofollow(&target) {
        Ok(file) => file,
        Err(_) => return result(Error::Io),
    };
    let opened = match original.metadata() {
        Ok(metadata)
            if metadata.file_type().is_file()
                && metadata.dev() == initial.dev()
                && metadata.ino() == initial.ino() => metadata,
        _ => {
            match hooks.as_mut() {
                Some(hook) => {
                    let _ = hook.close_file(original);
                }
                None => {
                    let _ = crate::sys::close_checked(original.into());
                }
            }
            return result(Error::Io);
        }
    };
    let saved_mode = opened.permissions().mode() & 0o7777;
    let original_close = match hooks.as_mut() {
        Some(hook) => hook.close_file(original),
        None => crate::sys::close_checked(original.into()),
    };
    if original_close.is_err() {
        return result(Error::Io);
    }

    let directory_bytes = parent_bytes(path);
    let directory = Path::new(std::ffi::OsStr::from_bytes(directory_bytes));
    let (mut temporary_file, temporary_path) = match create_temp(directory_bytes, TEMP_PREFIX) {
        Ok(value) => value,
        Err(TempError::Limit) => return result(Error::PathLimit),
        Err(TempError::Io) => return result(Error::Io),
    };

    if write_all(&mut temporary_file, bytes, |file, remaining| match hooks.as_deref_mut() {
        Some(hook) => hook.write(file, remaining),
        None => std::io::Write::write(file, remaining),
    })
    .is_err()
    {
        cleanup_temp(Some(temporary_file), &temporary_path);
        return result(Error::Io);
    }

    if temporary_file
        .set_permissions(fs::Permissions::from_mode(saved_mode))
        .is_err()
    {
        cleanup_temp(Some(temporary_file), &temporary_path);
        return result(Error::Io);
    }

    let sync_result = match hooks.as_deref_mut() {
        Some(hook) => hook.sync_file(&temporary_file),
        None => temporary_file.sync_all(),
    };
    if sync_result.is_err() {
        cleanup_temp(Some(temporary_file), &temporary_path);
        return result(Error::Io);
    }
    let mut state = result(Error::Io);
    state.file_synced = true;

    let temp_close = match hooks.as_mut() {
        Some(hook) => hook.close_file(temporary_file),
        None => crate::sys::close_checked(temporary_file.into()),
    };
    if temp_close.is_err() {
        remove_temp(&temporary_path);
        return state;
    }

    let rename_result = match hooks.as_deref_mut() {
        Some(hook) => hook.rename(&temporary_path, &target),
        None => fs::rename(&temporary_path, &target),
    };
    if rename_result.is_err() {
        remove_temp(&temporary_path);
        return state;
    }
    state.renamed = true;
    state.error = Error::Durability;

    let directory_sync = match hooks.as_deref_mut() {
        Some(hook) => hook.sync_directory(directory),
        None => File::open(directory).and_then(|file| file.sync_all()),
    };
    if directory_sync.is_ok() {
        state.error = Error::Ok;
        state.directory_synced = true;
    }
    state
}
