        Some(hook) => hook.write(file, remaining),
        None => std::io::Write::write(file, remaining),
    })
    .is_err()
    {
        cleanup_temp(Some(temporary_file), &temporary_path);
        return result(Error::Io);
    }

    let sync_result = match hooks.as_deref_mut() {
        Some(hook) => hook.sync_file(&temporary_file),
        None => temporary_file.sync_all(),
    };
    if sync_result.is_err() {
        cleanup_temp(Some(temporary_file), &temporary_path);
        return result(Error::Io);
