    27	static bool path_string(base_bytes path, char out[PATH_MAX])
    28	{
    29	    if (!base_bytes_valid(path) || path.len == 0) return false;
    30	    if (path.len >= PATH_MAX || memchr(path.ptr, '\0', path.len) != NULL) return false;
    31	    memcpy(out, path.ptr, path.len);
