    26	/// Failure reported by a native system service.
    27	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
    28	pub enum SystemError {
    29	    /// The requested random buffer exceeds the wrapper's fixed bound.
    30	    RandomRequestTooLarge { requested: usize, maximum: usize },
    31	    /// `SecRandomCopyBytes` returned a nonzero `OSStatus`.
    32	    RandomStatus(i32),
    33	    /// `getpeereid` failed; this is the `errno` value captured immediately.
    34	    PeerCredentialsErrno(i32),
    35	}
    36	
    37	impl fmt::Display for SystemError {
    38	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    39	        match self {
    40	            Self::RandomRequestTooLarge { requested, maximum } => {
    41	                write!(f, "random request of {requested} bytes exceeds {maximum}")
    42	            }
    43	            Self::RandomStatus(status) => {
    44	                write!(f, "SecRandomCopyBytes failed with OSStatus {status}")
    45	            }
    46	            Self::PeerCredentialsErrno(errno) => {
    47	                write!(f, "getpeereid failed with errno {errno}")
    48	            }
    49	        }
    50	    }
    51	}
    52	
    53	impl std::error::Error for SystemError {}
