    55	/// Fill `output` with bytes from Apple's default cryptographic random source.
    56	///
    57	/// Empty output succeeds without calling the native function. Requests above
    58	/// [`MAX_RANDOM_BYTES`] are rejected before any native call. If the native
    59	/// call fails, every byte in `output` is cleared before its status is returned.
    60	pub fn fill_random(output: &mut [u8]) -> Result<(), SystemError> {
    61	    if output.len() > MAX_RANDOM_BYTES {
    62	        return Err(SystemError::RandomRequestTooLarge {
    63	            requested: output.len(),
    64	            maximum: MAX_RANDOM_BYTES,
    65	        });
    66	    }
    67	    if output.is_empty() {
    68	        return Ok(());
    69	    }
    70	
    71	    let status = sys::fill_random(output);
    72	    random_result(status, output)
    73	}
    74	
    75	fn random_result(status: i32, output: &mut [u8]) -> Result<(), SystemError> {
    76	    if status == 0 {
    77	        Ok(())
    78	    } else {
    79	        output.fill(0);
    80	        Err(SystemError::RandomStatus(status))
    81	    }
    82	}
