    89	/// Return the user and group IDs associated with a connected peer socket.
    90	///
    91	/// The descriptor is borrowed only for the duration of this call. Credentials
    92	/// are returned as Darwin's 32-bit `uid_t` and `gid_t` values.
    93	pub fn peer_credentials(socket: BorrowedFd<'_>) -> Result<(u32, u32), SystemError> {
    94	    sys::peer_credentials(socket).map_err(SystemError::PeerCredentialsErrno)
    95	}
