    27	static bool path_string(base_bytes path, char out[PATH_MAX])
    28	{
    29	    if (!base_bytes_valid(path) || path.len == 0) return false;
    30	    if (path.len >= PATH_MAX || memchr(path.ptr, '\0', path.len) != NULL) return false;
    31	    memcpy(out, path.ptr, path.len);
    32	    out[path.len] = '\0';
    33	    return true;
    34	}
    35	
    36	static bool parent_path(const char *path, size_t length, char out[PATH_MAX])
    37	{
    38	    size_t slash = length;
    39	    while (slash > 0 && path[slash - 1] != '/') slash--;
    40	    if (slash == 0) {
    41	        memcpy(out, ".", 2);
    42	        return true;
    43	    }
    44	    size_t parent_length = slash == 1 ? 1 : slash - 1;
    45	    if (parent_length + sizeof(TEMP_SUFFIX) > PATH_MAX) return false;
    46	    memcpy(out, path, parent_length);
    47	    out[parent_length] = '\0';
    48	    return true;
    49	}
